      '你走 G1。接着把左边一路的口也封上。到这里，黑棋向下、向左的出路全没了。这三手你一个子都没挨着黑棋，但黑棋的活动空间已经缩掉一半 —— 这就是「先封口」。',
      '黑应 B7。黑棋转向上边找出路。B7 是黑棋唯一能跟上方联络的跳点，黑棋必须抢。',
