      '黑应 A6。黑棋在上边顽强做眼，A6 撑住 A 列一线的空间。',
      '你走 D1。从下方再顶一手，把黑棋左边的做眼空间压到只剩一路。',
      '黑应 E4。黑棋唯一的机会是往中间突，E4 是它最后的出口。白棋前面若没有封住下边，这一手就出去了。',
      '你走 A5。贴着黑棋左边紧气。到这里黑棋左边那一排（A4、B4、C4、D4）已经被压成一路，做不出第二个眼。',
