      '第 3 手若贪心去 G7 断黑棋上边的联络，黑棋从下边 D3 一路冲，你反倒被切成两块。本题下边比上边急。',
      '黑棋第 4 手若不走 B7 而走 D1 做眼，你 B7 一封，黑棋整块连眼位带联络一起没。所以系统选 B7 是对的，但你要理解：这是黑棋权衡之后的次优选择 —— 两块都想保，结果一块都没保住。',
