    era: '这题出自清代《官子谱》（1694 年成书，陶式玉编）。书名虽叫「官子」，实际收题以死活、手筋为主，是清代围棋技术水平的巅峰体现。这类「先封口再收气」的杀法，在日本被称为「追杀」的经典次序。它的价值不在形状，而在次序感 —— 什么时候该离得远远地封口，什么时候该贴身收气，这个判断比记住某个定式有用得多。',
