      '你走 F12，跟着长，继续贴。这叫滚打 —— 对方长一步，你就贴一步，对方的气永远比原来少。要点是贴着走（F12 挨着 G11），不要撞上去（比如 F11 硬顶）：贴着能继续追，撞上去会自紧气，还会把断点让给它。',
