    principle: '「送吃定形」是手筋中很反直觉的一类。普通棋理说不要白白送子，但这道题黑棋主动送了三颗子，而且送得心甘情愿。为什么？因为送吃有两个作用：第一，把白棋的应手固定住 —— 白棋除了提子，没有别的选择；第二，把黑棋自己的形状逼出来 —— J2、K1、J1 三手之后，黑棋右侧的眼位边界就清晰了。真正做眼的是第 7 手 K3，但如果没有前面三手的铺垫，K3 落下去也做不成眼。这类手筋叫送吃定形：用牺牲换确定。',
    era: '出自元代《玄玄棋经》。「送吃定形」是《玄玄棋经》中偏难的一类题目，因为它要求做题者跳出「不送子」的思维定式。这类题目最能体现 AI 与人类的思维差异：人类看到送三颗子会心疼，而 AI 完全不在乎 —— 它只看胜率。实际上现代 AI 在对局中经常主动送吃，有时候甚至送掉十几颗子的大龙，只为了换取角上的一个先手。这种大弃子思路在 2016 年之后深刻改变了人类围棋观。',
