    principle: '「厚势的价值在于借用。」厚势是围棋中最抽象的概念之一 —— 它本身不产生目数，但它让别处的作战变得有利。这道题里，黑棋左边的厚势就是这样的隐形资产：它值多少目？没人能算清；但它能让黑棋在中腹作战时不必担心后方。巩固厚势的正确方法不是守地，而是把它整理干净（C12）—— 让厚势真正成为坚实的后盾。反过来，如果后方不干净，厚势就变成了纸老虎：看着很大，但一作战就发现背后有洞。',
